export function mutatePrivacyGraph(source,kind){
  const graph=JSON.parse(source);
  if(kind==='empty')return asBytes({...graph,prompts:[],rawReceipts:[]});
  if(kind==='prompt-missing')graph.prompts.pop();
  if(kind==='identifier'){const bytes=Buffer.from('Alice Example approved this record');graph.prompts[0].bytesBase64=bytes.toString('base64');graph.prompts[0].sha256=sha256(bytes);}
  if(kind==='receipt-missing')graph.rawReceipts.pop();
  if(kind==='destination')graph.prompts[0].destination='production';
  if(kind==='detector-drift')graph.detectorRegistryDigest=H64('f');
  if(kind==='linkage')graph.linkageClaims.top1Millionths=100000;
  if(kind==='derivative-missing')graph.derivatives.pop();
  if(kind==='policy-substitution')graph.policyDigest=H64('f');
  if(kind==='policy-bytes-missing')graph.retentionPolicyBytes='';
  if(kind==='k-below-five'){const bytes=Buffer.from('workflow cohort 999 generalized constraints 1999');graph.prompts[0].bytesBase64=bytes.toString('base64');graph.prompts[0].sha256=sha256(bytes);}
  if(kind==='wrong-source-authority'||kind==='expired-use'||kind==='allowed-derivatives-empty'){const use=JSON.parse(graph.useAuthorizationBytes);if(kind==='wrong-source-authority')use.sourcePoolDigest=H64('f');if(kind==='expired-use')use.validThrough='2026-09-01T00:00:00Z';if(kind==='allowed-derivatives-empty')use.allowedDerivatives=[];graph.useAuthorizationBytes=asBytes(reseal(use,'authority'));}
  if(kind==='raw-authority-missing')graph.rawAuthorities.pop();
  if(kind==='encrypted-key-missing')graph.encryptedCorpus.keyId='';
  if(kind==='sanitizer-substitution'){const run=JSON.parse(graph.sanitizerRunBytes);run.identity='attacker';graph.sanitizerRunBytes=asBytes(reseal(run));}
  if(kind==='linkage-trial-substitution')graph.linkageTrials[0].linked=true;
  return asBytes(graph);
}

